-- T1 is open and has already read the row
BEGIN;
SELECT balance FROM account WHERE id = 42;   -- 100

-- T2, another session
UPDATE account SET balance = 120 WHERE id = 42;
COMMIT;

-- session A
SELECT balance FROM account WHERE id = 42;

-- session B, at the same moment
UPDATE account SET balance = 120 WHERE id = 42;

-- T1
BEGIN;
UPDATE account SET balance = 999 WHERE id = 42;
-- T1 has NOT committed

-- T2, another session
SELECT balance FROM account WHERE id = 42;   -- ?

-- T1, REPEATABLE READ
BEGIN;
SELECT balance FROM account WHERE id = 42;   -- 100

-- T2, another session
UPDATE account SET balance = 120 WHERE id = 42;
COMMIT;

-- T1, still the same transaction
SELECT balance FROM account WHERE id = 42;   -- ?

-- T1
BEGIN;
UPDATE account SET balance = balance - 10 WHERE id = 42;
-- T1 has NOT committed

-- T2, another session
UPDATE account SET balance = balance - 20 WHERE id = 42;   -- ?

BEGIN;   -- READ COMMITTED
SELECT stock FROM product WHERE id = 7;    -- the application reads 5
-- the application computes 5 - 1 = 4
UPDATE product SET stock = 4 WHERE id = 7;
COMMIT;

-- reporting session, opened at 09:00 and left open all day
BEGIN;
SELECT count(*) FROM orders;
-- ... idle inside the transaction until 18:00 ...
COMMIT;

-- T1: REPEATABLE READ, starts first
BEGIN;
SELECT balance FROM account WHERE id = 42;      -- 100

-- T2
BEGIN;
UPDATE account SET balance = 120 WHERE id = 42;
-- T2 has NOT committed yet

-- T1
SELECT balance FROM account WHERE id = 42;      -- (a)

-- T2
COMMIT;

-- T1
SELECT balance FROM account WHERE id = 42;      -- (b)

